// `forge lint --generated-drift` — the gate on hand-edited generated files.
//
// ── Why a lint gate exists at all ─────────────────────────────────────
//
// forge already DETECTS this: every Tier-1 (regenerated-every-run) file
// carries a `// Code generated by forge. DO NOT EDIT.` banner plus its
// own content hash, and generator.ScanProjectDrift reports every file
// whose bytes no longer match that hash. Until this step, though, the
// only surfaces that acted on the signal were `forge generate` (the
// pre-pipeline stomp guard) and `forge ci verify-generated`, which
// leaves a real hole:
//
//   - the stomp guard fires AT generate time, which is by definition the
//     moment the edit is about to be destroyed. Everything between the
//     edit and the next generate is silent.
//   - the guard also SCOPES its drift set to the emitters that would run
//     this invocation (generate_tier1_scope.go). Drift in an out-of-scope
//     file is a warning, not a failure — so an edit to, say,
//     pkg/app/testing.go under a `--steps=…` run is waved through.
//   - `forge project audit` reports the same drift, but audit is a
//     non-gating snapshot by design: it always exits 0.
//
// So an agent (or a human) could hand-edit a DO-NOT-EDIT file, watch
// every check pass, commit it, and lose the work at the next regenerate.
// `forge lint` is the check that runs BETWEEN edits and generate — in the
// agent loop and in the CI lint job — so that is where the gate belongs.
// It scans the whole tree with no emitter-scope filter: if forge owns the
// bytes and the bytes changed, lint fails.
//
// ── No false positives ────────────────────────────────────────────────
//
// The gate reports exactly what generator.ScanProjectDrift reports (see
// that file for the by-construction exclusions: scaffold-once files,
// disowned paths, files forge never wrote, pristine-older renders,
// formatter-only churn, Tier-2-managed starters), minus one more class
// handled here: the `unverified-legacy` sentinel. That marker means the
// one-time legacy-manifest migration could not ESTABLISH provenance —
// it is not evidence of an edit — so it is reported as a warning that
// routes the user to `forge generate`, never as a gating error.
//
// A gate that cries wolf gets disabled, so every one of those exclusions
// is load-bearing.
package lint

import (
	"fmt"

	"github.com/reliant-labs/forge/internal/checksums"
	"github.com/reliant-labs/forge/internal/generator"
	"github.com/reliant-labs/forge/internal/linter/finding"
)

// Rule ids for the two outcomes. They are separate so a CI consumer can
// filter on the gating one without also matching the advisory one.
const (
	// generatedDriftRule marks a forge-generated file whose bytes changed
	// after forge stamped them. Error severity — this gates.
	generatedDriftRule = "forge-generated-file-edited"
	// generatedUnverifiedRule marks a file whose provenance the legacy
	// manifest migration could not establish. Warning severity.
	generatedUnverifiedRule = "forge-generated-file-unverified"
)

// generatedDriftFindings scans the project at root and returns one
// finding per forge-owned file whose on-disk bytes drifted from the
// render forge certified.
func generatedDriftFindings(root string) ([]finding.Finding, error) {
	cs, err := generator.LoadChecksums(root)
	if err != nil {
		return nil, fmt.Errorf("load .forge ownership state: %w", err)
	}
	drift := generator.ScanProjectDrift(root, cs)
	out := make([]finding.Finding, 0, len(drift))
	for _, d := range drift {
		if d.Unverified {
			out = append(out, finding.Finding{
				Rule:     generatedUnverifiedRule,
				Severity: finding.SeverityWarning,
				Path:     d.Path,
				Message: fmt.Sprintf(
					"%s carries the %q marker: forge could not establish whether these bytes are its own output when this project migrated off the legacy checksums manifest.",
					d.Path, checksums.UnverifiedMarkerValue),
				Remediation: fmt.Sprintf(
					"resolve it once: `forge generate --force` to regenerate %s from the current templates, or `forge project disown %s --reason \"<why>\"` to keep the current bytes.",
					d.Path, d.Path),
			})
			continue
		}
		out = append(out, finding.Finding{
			Rule:     generatedDriftRule,
			Severity: finding.SeverityError,
			Path:     d.Path,
			Message: fmt.Sprintf(
				"%s is forge-generated (it carries the `Code generated by forge. DO NOT EDIT.` banner) and was edited after forge wrote it — the next `forge generate` regenerates the file and these edits are lost.",
				d.Path),
			Remediation: fmt.Sprintf(
				"revert the edit (`git checkout -- %s`) and move the customization to a user-owned file, or run `forge project disown %s --reason \"<why>\"` to take permanent ownership of it (one-way: forge stops regenerating it).",
				d.Path, d.Path),
		})
	}
	return out, nil
}

// collectGeneratedDriftJSON is the --json arm. The bool is the gating
// verdict, mirroring runGeneratedDriftLint's error exactly.
func collectGeneratedDriftJSON(root string) ([]lintJSONFinding, bool, error) {
	findings, err := generatedDriftFindings(root)
	if err != nil {
		return nil, false, err
	}
	out := findingsToJSON(findings)
	gated := false
	for _, f := range findings {
		if f.Severity == finding.SeverityError {
			gated = true
			break
		}
	}
	return out, gated, nil
}
